async function hullTarget(page){
 const candidates=await page.evaluate(()=>{const Y=window.__yard,C=Y.C,parent=Y.ship.parts.find(p=>p.id===178),T=C.structTriangles(parent),out=[];for(let i=0;i<T.length;i+=9){const a=Array.from(T.slice(i,i+3)),b=Array.from(T.slice(i+3,i+6)),c=Array.from(T.slice(i+6,i+9)),n=C.cross(C.sub(b,a),C.sub(c,a)),area=C.len(n);if(area<1)continue;const normal=C.norm(n);if(normal[1]<.5)continue;for(const w of [[1/3,1/3,1/3],[.6,.2,.2],[.2,.6,.2],[.2,.2,.6]]){const point=C.add(C.add(C.mul(a,w[0]),C.mul(b,w[1])),C.mul(c,w[2]));if(point[0]>=650&&point[0]<=1300)out.push({p:point,dir:normal,r:1800,area});}}return out.sort((a,b)=>(Math.abs(a.p[0]-700)+Math.abs(a.p[2])*.2)-(Math.abs(b.p[0]-700)+Math.abs(b.p[2])*.2)||b.area-a.area).slice(0,30);});
 for(const q of candidates){await aim(page,{p:[q.p[0],q.p[1],q.p[2]+500],dir:[0,1,.0006],r:1800});const pixel=await page.evaluate(q=>{const Y=window.__yard,pixel=Y.view().project(q.p).slice(0,2),hit=Y.pick(...pixel,{parts:false,fits:false});return document.elementFromPoint(...pixel)===Y.view().canvas&&(hit?.parentStructureId??hit?.part?.id)===178?{pixel,point:hit.p,parentStructureId:hit.parentStructureId??hit.part.id,surfaceId:hit.hostSurfaceId}:null;},q);if(pixel)return{...q,...pixel};}throw Error('No real parent hull target is available');
}
